/**
 * Crafty Rose Social Studio — server entry points.
 *
 * Phase 1: serves the app shell, sets up the database spreadsheet and
 * returns dashboard data (clearly flagged as SAMPLE until real
 * platform connections exist in Phase 3).
 */

var APP = {
  name: 'Crafty Rose Social Studio',
  version: '0.2.0',
  timeZone: 'America/Halifax',
  siteUrl: 'https://studio.craftyrosegifts.ca'
};

/** Web app entry point. */
function doGet() {
  var tpl = HtmlService.createTemplateFromFile('Index');
  tpl.siteUrl = APP.siteUrl;
  return tpl.evaluate()
    .setTitle(APP.name)
    .setFaviconUrl(APP.siteUrl + '/rose64.png')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.DEFAULT);
}

/** Lets HTML templates pull in other HTML files: <?!= include('Styles') ?> */
function include(name) {
  return HtmlService.createHtmlOutputFromFile(name).getContent();
}

/**
 * Called by the interface on load. Makes sure the database exists,
 * then returns everything the shell and dashboard need.
 */
function getAppBootstrap() {
  var db = Db.ensure();
  return {
    app: { name: APP.name, version: APP.version, timeZone: APP.timeZone },
    user: { email: Session.getActiveUser().getEmail() },
    database: { url: db.getUrl(), ready: true },
    now: new Date().toISOString(),
    dashboard: SampleData.dashboard(),
    posts: studioSummary_()
  };
}

/** Run once from the editor (or let the app call it) to create the database. */
function setup() {
  var db = Db.ensure();
  Logger.log('Database ready: ' + db.getUrl());
}

/** Real post counts and the next scheduled posts (used by the dashboard and sidebar). */
function studioSummary_() {
  var posts = listPosts();
  var scheduled = posts.filter(function (p) { return p.status === 'scheduled'; });
  return {
    counts: {
      scheduled: scheduled.length,
      drafts: posts.filter(function (p) { return p.status === 'draft'; }).length,
      media: Db.all('Media').length
    },
    upcoming: scheduled.slice(0, 5)
  };
}

/** Lightweight refresh for the sidebar counts and dashboard after saving. */
function getStudioSummary() { return studioSummary_(); }

/**
 * Crafty Rose Social Studio — database layer.
 *
 * Application data lives in a private Google Sheet ("Crafty Rose Studio — Data")
 * inside the "Crafty Rose Social Studio" Drive folder. One tab per table.
 *
 * Security: access tokens are NEVER written to the spreadsheet. They are kept in
 * Apps Script's private property store (see Phase 3), which only this script can read.
 */

var DB_SCHEMA = {
  Posts: [
    'id', 'title', 'postType', 'status', 'baseCaption', 'baseHashtags', 'link',
    'mediaIds', 'platforms', 'scheduledAt', 'timeZone', 'inQueue', 'notes', 'createdAt', 'updatedAt'
  ],
  // One row per platform for each post, so every platform has its own caption,
  // settings and publishing status (e.g. Instagram published, TikTok failed → retry TikTok only).
  PostTargets: [
    'id', 'postId', 'platform', 'accountId', 'format', 'caption', 'hashtags', 'title',
    'description', 'destinationUrl', 'coverMediaId', 'mediaIds', 'options', 'status',
    'scheduledAt', 'publishedAt', 'platformPostId', 'platformUrl', 'attempts',
    'lastError', 'lastAttemptAt', 'createdAt', 'updatedAt'
  ],
  Media: [
    'id', 'fileName', 'driveFileId', 'folder', 'tags', 'kind', 'mimeType', 'sizeBytes',
    'width', 'height', 'aspectRatio', 'durationSec', 'container', 'videoCodec',
    'audioCodec', 'frameRate', 'thumbnailFileId', 'compatibility', 'parentMediaId',
    'isOriginal', 'uploadedAt', 'notes', 'driveFolderId', 'thumbData', 'bitrate', 'rotation',
    'moovAtFront', 'hasEditList', 'imageFormat'
  ],
  Accounts: [
    'id', 'platform', 'accountName', 'username', 'externalId', 'status', 'scopes',
    'capabilities', 'connectedAt', 'lastSyncAt', 'lastError', 'notes'
  ],
  Captions: [
    'id', 'title', 'category', 'body', 'hashtagGroupId', 'platforms', 'timesUsed',
    'createdAt', 'updatedAt'
  ],
  HashtagGroups: ['id', 'name', 'category', 'hashtags', 'createdAt', 'updatedAt'],
  AccountMetrics: [
    'id', 'date', 'platform', 'accountId', 'followers', 'reach', 'views', 'engagements',
    'likes', 'comments', 'shares', 'saves', 'videoViews', 'capturedAt'
  ],
  PostMetrics: [
    'id', 'targetId', 'platform', 'capturedAt', 'views', 'reach', 'likes', 'comments',
    'shares', 'saves', 'videoViews', 'watchTimeSec'
  ],
  ActivityLog: [
    'id', 'timestamp', 'level', 'type', 'postId', 'targetId', 'platform', 'message', 'details'
  ],
  Settings: ['key', 'value', 'updatedAt']
};

var MEDIA_FOLDERS = [
  'Product Photography', 'Tumblers and Drinkware', 'Apparel', 'Personalized Gifts',
  'Seasonal Products', 'Christmas', 'Behind the Scenes', 'Videos and Reels',
  'General Marketing'
];

var DEFAULT_SETTINGS = {
  timeZone: 'America/Halifax',
  brandLightGreen: '#8BC4A9',
  brandDarkGreen: '#4C6D5E',
  defaultPublishTime: '10:00',
  queueSlots: '[{"day":2,"time":"10:00"},{"day":4,"time":"18:30"},{"day":6,"time":"10:00"}]',
  schemaVersion: '1'
};

var Db = (function () {
  var PROP_DB = 'DB_SPREADSHEET_ID';
  var PROP_ROOT = 'DRIVE_ROOT_FOLDER_ID';
  var cached = null;

  function props() { return PropertiesService.getScriptProperties(); }

  function tryOpen(id) {
    if (!id) return null;
    try { return SpreadsheetApp.openById(id); } catch (e) { return null; }
  }

  // Drive access uses the Drive REST API with the narrow "drive.file" permission,
  // so the studio can only see the files and folders it created itself.
  var Drive = {
    req: function (method, path, body, query) {
      var url = 'https://www.googleapis.com/drive/v3/' + path;
      if (query) {
        url += '?' + Object.keys(query).map(function (k) {
          return encodeURIComponent(k) + '=' + encodeURIComponent(query[k]);
        }).join('&');
      }
      var res = UrlFetchApp.fetch(url, {
        method: method,
        contentType: 'application/json',
        payload: body ? JSON.stringify(body) : undefined,
        headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() },
        muteHttpExceptions: true
      });
      var code = res.getResponseCode();
      if (code >= 300) throw new Error('Drive API ' + code + ': ' + res.getContentText().slice(0, 300));
      var text = res.getContentText();
      return text ? JSON.parse(text) : {};
    },
    exists: function (id) {
      if (!id) return false;
      try { return !Drive.req('get', 'files/' + id, null, { fields: 'id,trashed' }).trashed; }
      catch (e) { return false; }
    },
    folder: function (name, parentId) {
      var q = "mimeType='application/vnd.google-apps.folder' and trashed=false and name='" +
        name.replace(/'/g, "\\'") + "'" + (parentId ? " and '" + parentId + "' in parents" : '');
      var found = Drive.req('get', 'files', null, { q: q, fields: 'files(id)', pageSize: 1 }).files;
      if (found && found.length) return found[0].id;
      var body = { name: name, mimeType: 'application/vnd.google-apps.folder' };
      if (parentId) body.parents = [parentId];
      return Drive.req('post', 'files', body, { fields: 'id' }).id;
    },
    move: function (fileId, parentId) {
      var cur = Drive.req('get', 'files/' + fileId, null, { fields: 'parents' }).parents || [];
      Drive.req('patch', 'files/' + fileId, {}, { addParents: parentId, removeParents: cur.join(','), fields: 'id' });
    },
    copy: function (fileId, name, parentId) {
      return Drive.req('post', 'files/' + fileId + '/copy', { name: name, parents: [parentId] }, { fields: 'id' }).id;
    },
    children: function (parentId) {
      return Drive.req('get', 'files', null, {
        q: "'" + parentId + "' in parents and trashed=false",
        fields: 'files(id,name,createdTime)', orderBy: 'createdTime desc', pageSize: 100
      }).files || [];
    },
    trash: function (fileId) { Drive.req('patch', 'files/' + fileId, { trashed: true }, { fields: 'id' }); }
  };

  /** Creates (once) the studio's Drive folders and returns their IDs. */
  function ensureFolders() {
    var p = props();
    var rootId = p.getProperty(PROP_ROOT);
    var version = 'v2:' + MEDIA_FOLDERS.length;
    if (p.getProperty('DRIVE_FOLDERS_READY') === version && Drive.exists(rootId)) {
      return {
        root: rootId,
        backups: p.getProperty('DRIVE_BACKUPS_FOLDER_ID'),
        media: p.getProperty('DRIVE_MEDIA_FOLDER_ID'),
        mediaFolders: JSON.parse(p.getProperty('DRIVE_MEDIA_SUBFOLDERS') || '{}')
      };
    }
    if (!Drive.exists(rootId)) {
      rootId = Drive.folder('Crafty Rose Social Studio', null);
      p.setProperty(PROP_ROOT, rootId);
    }
    var backups = Drive.folder('Backups', rootId);
    var media = Drive.folder('Media Library', rootId);
    var sub = {};
    MEDIA_FOLDERS.forEach(function (name) { sub[name] = Drive.folder(name, media); });
    p.setProperties({
      DRIVE_BACKUPS_FOLDER_ID: backups,
      DRIVE_MEDIA_FOLDER_ID: media,
      DRIVE_MEDIA_SUBFOLDERS: JSON.stringify(sub),
      DRIVE_FOLDERS_READY: version
    });
    return { root: rootId, backups: backups, media: media, mediaFolders: sub };
  }

  function ensureSheets(ss) {
    Object.keys(DB_SCHEMA).forEach(function (name) {
      var headers = DB_SCHEMA[name];
      var sh = ss.getSheetByName(name) || ss.insertSheet(name);
      var current = sh.getLastColumn() > 0
        ? sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0] : [];
      // Add any missing columns at the end (safe schema upgrades, never deletes data).
      var missing = headers.filter(function (h) { return current.indexOf(h) === -1; });
      if (current.length === 0) {
        sh.getRange(1, 1, 1, headers.length).setValues([headers]);
      } else if (missing.length) {
        sh.getRange(1, current.length + 1, 1, missing.length).setValues([missing]);
      }
      var width = Math.max(current.length + missing.length, headers.length);
      sh.getRange(1, 1, 1, width)
        .setFontWeight('bold').setBackground('#EAF3EE').setFontColor('#3D5A4D');
      sh.setFrozenRows(1);
    });
    var stray = ss.getSheetByName('Sheet1');
    if (stray && ss.getSheets().length > 1) ss.deleteSheet(stray);
  }

  function ensureSettings(ss) {
    var sh = ss.getSheetByName('Settings');
    var rows = sh.getLastRow() > 1 ? sh.getRange(2, 1, sh.getLastRow() - 1, 1).getValues() : [];
    var keys = rows.map(function (r) { return r[0]; });
    var now = new Date().toISOString();
    Object.keys(DEFAULT_SETTINGS).forEach(function (k) {
      if (keys.indexOf(k) === -1) sh.appendRow([k, DEFAULT_SETTINGS[k], now]);
    });
  }

  function ensure() {
    if (cached) return cached;
    var lock = LockService.getScriptLock();
    lock.waitLock(20000);
    try {
      var ss = tryOpen(props().getProperty(PROP_DB));
      if (!ss) {
        var folders = ensureFolders();
        ss = SpreadsheetApp.create('Crafty Rose Studio — Data');
        Drive.move(ss.getId(), folders.root);
        props().setProperty(PROP_DB, ss.getId());
        ss.setSpreadsheetTimeZone(APP.timeZone);
      }
      // Only touch the sheet structure when the schema has changed (keeps loading fast).
      var schemaKey = JSON.stringify(DB_SCHEMA).length + ':' + Object.keys(DB_SCHEMA).length + ':' + Object.keys(DEFAULT_SETTINGS).length;
      if (props().getProperty('DB_SCHEMA_KEY') !== schemaKey || props().getProperty('DB_SCHEMA_FOR') !== ss.getId()) {
        ensureSheets(ss);
        ensureSettings(ss);
        props().setProperties({ DB_SCHEMA_KEY: schemaKey, DB_SCHEMA_FOR: ss.getId() });
      }
      cached = ss;
      return ss;
    } finally {
      lock.releaseLock();
    }
  }

  /** Read a whole table as an array of objects. */
  function all(table) {
    var sh = ensure().getSheetByName(table);
    var last = sh.getLastRow();
    if (last < 2) return [];
    var values = sh.getRange(1, 1, last, sh.getLastColumn()).getValues();
    var headers = values.shift();
    return values.map(function (row) {
      var o = {};
      headers.forEach(function (h, i) { o[h] = row[i]; });
      return o;
    });
  }

  /** Append a row object to a table; returns the object with id/timestamps. */
  function insert(table, obj) {
    var sh = ensure().getSheetByName(table);
    var headers = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];
    var now = new Date().toISOString();
    if (headers.indexOf('id') !== -1 && !obj.id) obj.id = Utilities.getUuid();
    if (headers.indexOf('createdAt') !== -1 && !obj.createdAt) obj.createdAt = now;
    if (headers.indexOf('updatedAt') !== -1) obj.updatedAt = now;
    sh.appendRow(headers.map(function (h) { return toCell(obj[h]); }));
    return obj;
  }

  function sheetInfo(table) {
    var sh = ensure().getSheetByName(table);
    var headers = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];
    return { sh: sh, headers: headers, idCol: headers.indexOf('id') };
  }

  function findRow(info, id) {
    var last = info.sh.getLastRow();
    if (last < 2) return -1;
    var ids = info.sh.getRange(2, info.idCol + 1, last - 1, 1).getValues();
    for (var i = 0; i < ids.length; i++) if (String(ids[i][0]) === String(id)) return i + 2;
    return -1;
  }

  function toCell(v) {
    if (v !== null && typeof v === 'object') return JSON.stringify(v);
    if (v === undefined || v === null) return '';
    // Stop Sheets treating text like "=..." as a formula.
    if (typeof v === 'string' && /^[=+\-@]/.test(v)) return "'" + v;
    return v;
  }

  /** Read one row by id. */
  function get(table, id) {
    var info = sheetInfo(table);
    var row = findRow(info, id);
    if (row < 0) return null;
    var vals = info.sh.getRange(row, 1, 1, info.headers.length).getValues()[0];
    var o = {};
    info.headers.forEach(function (h, i) { o[h] = vals[i]; });
    return o;
  }

  /** Merge fields into an existing row. */
  function update(table, id, patch) {
    var info = sheetInfo(table);
    var row = findRow(info, id);
    if (row < 0) throw new Error(table + ' item not found');
    var range = info.sh.getRange(row, 1, 1, info.headers.length);
    var vals = range.getValues()[0];
    if (info.headers.indexOf('updatedAt') !== -1) patch.updatedAt = new Date().toISOString();
    info.headers.forEach(function (h, i) { if (h in patch && h !== 'id') vals[i] = toCell(patch[h]); });
    range.setValues([vals]);
    return get(table, id);
  }

  /** Delete rows matching a predicate on one column. */
  function removeWhere(table, column, value) {
    var info = sheetInfo(table);
    var col = info.headers.indexOf(column);
    var last = info.sh.getLastRow();
    if (col < 0 || last < 2) return 0;
    var vals = info.sh.getRange(2, col + 1, last - 1, 1).getValues();
    var n = 0;
    for (var i = vals.length - 1; i >= 0; i--) {
      if (String(vals[i][0]) === String(value)) { info.sh.deleteRow(i + 2); n++; }
    }
    return n;
  }

  function withLock(fn) {
    var lock = LockService.getScriptLock();
    lock.waitLock(20000);
    try { return fn(); } finally { lock.releaseLock(); }
  }

  /** Append an entry to the activity log. */
  function log(level, type, message, extra) {
    extra = extra || {};
    return insert('ActivityLog', {
      timestamp: new Date().toISOString(), level: level, type: type, message: message,
      postId: extra.postId || '', targetId: extra.targetId || '',
      platform: extra.platform || '', details: extra.details || ''
    });
  }

  /** Copy the database into Drive › Crafty Rose Social Studio › Backups (keeps the latest 8). */
  function backup() {
    var ss = ensure();
    var folders = ensureFolders();
    var stamp = Utilities.formatDate(new Date(), APP.timeZone, 'yyyy-MM-dd HHmm');
    var name = 'Studio backup ' + stamp;
    SpreadsheetApp.flush();
    Drive.copy(ss.getId(), name, folders.backups);
    Drive.children(folders.backups).slice(8).forEach(function (f) { Drive.trash(f.id); });
    log('success', 'backup', 'Database backed up (' + stamp + ')');
    return { ok: true, name: name };
  }

  return {
    ensure: ensure, all: all, insert: insert, get: get, update: update, removeWhere: removeWhere,
    withLock: withLock, log: log, backup: backup, folders: ensureFolders, drive: Drive
  };
})();

/** Exposed to the interface: Settings › "Back up now". */
function backupDatabase() { return Db.backup(); }

/**
 * SAMPLE DATA — for designing the dashboard in Phase 1 only.
 *
 * Nothing here comes from a real social media account. Every response carries
 * `isSample: true` and the interface shows a clear "Sample data" label.
 * This file is removed/bypassed once real accounts are connected (Phase 3–4).
 */

var SampleData = (function () {

  function seeded(seed) {
    var s = seed;
    return function () { s = (s * 9301 + 49297) % 233280; return s / 233280; };
  }

  function isoInDays(days, hour, minute) {
    var d = new Date();
    d.setDate(d.getDate() + days);
    d.setHours(hour, minute || 0, 0, 0);
    return d.toISOString();
  }

  function engagementSeries(n) {
    var rnd = seeded(42);
    var out = [];
    var base = 140;
    for (var i = n - 1; i >= 0; i--) {
      var d = new Date(); d.setDate(d.getDate() - i);
      var weekend = (d.getDay() === 0 || d.getDay() === 6) ? 35 : 0;
      base += (rnd() - 0.42) * 14;
      out.push({ date: Utilities.formatDate(d, APP.timeZone, 'yyyy-MM-dd'),
                 value: Math.max(40, Math.round(base + weekend + rnd() * 40)) });
    }
    return out;
  }

  function dashboard() {
    var platforms = [
      { id: 'instagram', name: 'Instagram', handle: '@craftyrosegifts', followers: 1248, change: 3.4 },
      { id: 'tiktok',    name: 'TikTok',    handle: '@craftyrosegifts', followers: 2310, change: 6.1 },
      { id: 'facebook',  name: 'Facebook',  handle: 'Crafty Rose Gifts', followers: 862,  change: 1.2 },
      { id: 'pinterest', name: 'Pinterest', handle: '@craftyrosegifts', followers: 397,  change: 2.8 },
      { id: 'youtube',   name: 'YouTube',   handle: '@craftyrosegifts', followers: 184,  change: 4.5 }
    ];
    var series = engagementSeries(90);
    var last30 = series.slice(-30).reduce(function (a, p) { return a + p.value; }, 0);
    var prev30 = series.slice(-60, -30).reduce(function (a, p) { return a + p.value; }, 0);

    return {
      isSample: true,
      generatedAt: new Date().toISOString(),
      totals: {
        followers: platforms.reduce(function (a, p) { return a + p.followers; }, 0),
        followersChange: 3.9,
        scheduled: 7,
        publishedThisMonth: 11,
        engagement30: last30,
        engagementChange: Math.round(((last30 - prev30) / prev30) * 1000) / 10
      },
      platforms: platforms,
      engagementSeries: series,
      upcoming: [
        { id: 'p1', title: 'Teacher appreciation tumblers', caption: 'Personalized tumblers for the teachers who make every day brighter 🍎 Order by Friday for…', type: 'photo', category: 'drinkware', platforms: ['instagram', 'facebook'], scheduledAt: isoInDays(1, 10, 30), status: 'scheduled' },
        { id: 'p2', title: 'Ornament making — behind the scenes', caption: 'A peek at how each Christmas ornament gets its name ✨', type: 'video', category: 'christmas', platforms: ['instagram', 'tiktok', 'youtube', 'facebook'], scheduledAt: isoInDays(2, 18, 0), status: 'scheduled' },
        { id: 'p3', title: 'Custom name hoodies restock', caption: 'They’re back! Cozy custom hoodies in five new colours…', type: 'photo', category: 'apparel', platforms: ['instagram', 'facebook', 'pinterest'], scheduledAt: isoInDays(4, 12, 0), status: 'scheduled' },
        { id: 'p4', title: 'Holiday craft fair announcement', caption: 'Come see us this weekend! Booth details and fair hours inside 🎄', type: 'photo', category: 'event', platforms: ['facebook', 'instagram'], scheduledAt: isoInDays(5, 9, 0), status: 'attention' },
        { id: 'p5', title: 'Gift guide: under $30', caption: 'Thoughtful handmade gifts that won’t break the bank…', type: 'carousel', category: 'gifts', platforms: ['pinterest', 'instagram'], scheduledAt: isoInDays(7, 19, 30), status: 'draft' }
      ],
      activity: [
        { level: 'success', platform: 'instagram', message: 'Reel “Vinyl pressing in slow motion” published', at: isoInDays(0, 9, 2) },
        { level: 'error',   platform: 'tiktok',    message: 'TikTok upload failed — connection expired. Reconnect TikTok and retry.', at: isoInDays(-1, 18, 1) },
        { level: 'success', platform: 'facebook',  message: 'Post “Fall mug collection” published', at: isoInDays(-1, 12, 0) },
        { level: 'warning', platform: 'instagram', message: 'Craft fair post needs a cover image before it can be scheduled', at: isoInDays(-2, 16, 40) },
        { level: 'success', platform: 'pinterest', message: 'Pin “Personalized wine tumblers” published', at: isoInDays(-3, 20, 15) }
      ]
    };
  }

  return { dashboard: dashboard };
})();

/**
 * Crafty Rose Social Studio — Media Library (server side).
 *
 * Files are uploaded straight from the browser to Google Drive (into the
 * "Crafty Rose Social Studio › Media Library › <folder>" folders), then
 * registered here. Originals are never modified; optimized copies (Phase 5)
 * will be saved as new files linked by `parentMediaId`.
 */

var MEDIA_JSON_FIELDS = ['tags', 'compatibility'];

function parseMediaRow_(r) {
  var o = {};
  Object.keys(r).forEach(function (k) { o[k] = r[k]; });
  MEDIA_JSON_FIELDS.forEach(function (k) {
    if (typeof o[k] === 'string' && o[k]) { try { o[k] = JSON.parse(o[k]); } catch (e) { /* keep string */ } }
    if (!o[k]) o[k] = k === 'tags' ? [] : null;
  });
  ['sizeBytes', 'width', 'height', 'durationSec', 'frameRate', 'bitrate', 'rotation'].forEach(function (k) {
    o[k] = o[k] === '' ? null : Number(o[k]);
  });
  o.uploadedAt = o.uploadedAt instanceof Date ? o.uploadedAt.toISOString() : String(o.uploadedAt || '');
  return o;
}

/** Everything the browser needs to upload directly to Drive. */
function getUploadContext() {
  Db.ensure();
  var f = Db.folders();
  return {
    token: ScriptApp.getOAuthToken(),
    expiresInSec: 3000,
    folders: MEDIA_FOLDERS.map(function (name) { return { name: name, id: f.mediaFolders[name] }; })
  };
}

/** List the whole library, newest first. */
function listMedia() {
  return Db.all('Media').map(parseMediaRow_).sort(function (a, b) {
    return a.uploadedAt < b.uploadedAt ? 1 : -1;
  });
}

/** Save a newly uploaded file's details. */
function registerMedia(m) {
  Db.ensure();
  if (!m || !m.driveFileId) throw new Error('Missing Drive file');
  var allowed = DB_SCHEMA.Media;
  var row = {};
  allowed.forEach(function (k) { if (k in m) row[k] = m[k]; });
  row.uploadedAt = new Date().toISOString();
  row.isOriginal = true;
  if (row.thumbData && String(row.thumbData).length > 48000) row.thumbData = '';
  var saved = Db.withLock(function () { return Db.insert('Media', row); });
  Db.log('success', 'media', 'Uploaded “' + row.fileName + '” to ' + row.folder);
  return parseMediaRow_(saved);
}

/** Rename, re-folder, tag or annotate a media item. */
function updateMedia(id, patch) {
  Db.ensure();
  var current = Db.get('Media', id);
  if (!current) throw new Error('Media not found');
  var clean = {};
  if (patch.fileName && patch.fileName !== current.fileName) {
    clean.fileName = String(patch.fileName).slice(0, 200);
    Db.drive.req('patch', 'files/' + current.driveFileId, { name: clean.fileName }, { fields: 'id' });
  }
  if (patch.folder && patch.folder !== current.folder) {
    var folders = Db.folders().mediaFolders;
    if (!folders[patch.folder]) throw new Error('Unknown folder');
    Db.drive.move(current.driveFileId, folders[patch.folder]);
    clean.folder = patch.folder;
    clean.driveFolderId = folders[patch.folder];
  }
  if (patch.tags) clean.tags = patch.tags.map(function (t) { return String(t).trim().toLowerCase(); }).filter(String).slice(0, 30);
  if ('notes' in patch) clean.notes = String(patch.notes || '').slice(0, 2000);
  if ('compatibility' in patch) clean.compatibility = patch.compatibility;
  var saved = Db.withLock(function () { return Db.update('Media', id, clean); });
  return parseMediaRow_(saved);
}

/**
 * Move a media file to the Drive trash (recoverable for 30 days) and remove it
 * from the library. Refuses if posts still use it, unless `force` is true.
 */
function deleteMedia(id, force) {
  Db.ensure();
  var item = Db.get('Media', id);
  if (!item) return { ok: true };
  var usedBy = Db.all('Posts').filter(function (p) { return String(p.mediaIds || '').indexOf(id) !== -1; })
    .map(function (p) { return p.title || 'Untitled post'; });
  if (usedBy.length && !force) return { ok: false, usedBy: usedBy };
  try { Db.drive.trash(item.driveFileId); } catch (e) { /* already gone */ }
  Db.withLock(function () { Db.removeWhere('Media', 'id', id); });
  Db.log('info', 'media', 'Moved “' + item.fileName + '” to the Drive trash');
  return { ok: true };
}

/**
 * Crafty Rose Social Studio — posts, drafts and the publishing queue.
 *
 * A post is stored once (Posts) with one row per platform (PostTargets), so each
 * platform keeps its own caption, settings and publishing status.
 *
 * Phase 2 note: "Scheduled" posts are saved and shown everywhere, but nothing is
 * sent to a platform until accounts are connected in Phase 3.
 */

var POST_STATUSES = ['draft', 'scheduled', 'publishing', 'published', 'failed', 'attention', 'partial'];
var PLATFORM_IDS = ['instagram', 'facebook', 'tiktok', 'youtube', 'pinterest'];

function iso_(v) { return v instanceof Date ? v.toISOString() : String(v || ''); }
function json_(v, fallback) {
  if (v === '' || v === null || v === undefined) return fallback;
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return fallback; }
}

function parsePost_(r) {
  return {
    id: r.id, title: r.title, postType: r.postType, status: r.status,
    baseCaption: r.baseCaption, baseHashtags: r.baseHashtags, link: r.link,
    mediaIds: json_(r.mediaIds, []), platforms: json_(r.platforms, []),
    scheduledAt: iso_(r.scheduledAt), inQueue: r.inQueue === true || r.inQueue === 'TRUE',
    notes: r.notes, createdAt: iso_(r.createdAt), updatedAt: iso_(r.updatedAt)
  };
}

function parseTarget_(r) {
  return {
    id: r.id, postId: r.postId, platform: r.platform, format: r.format,
    customize: json_(r.options, {}).customize === true,
    caption: r.caption, hashtags: r.hashtags, title: r.title, description: r.description,
    destinationUrl: r.destinationUrl, coverMediaId: r.coverMediaId,
    mediaIds: json_(r.mediaIds, []), options: json_(r.options, {}), status: r.status,
    scheduledAt: iso_(r.scheduledAt), publishedAt: iso_(r.publishedAt),
    platformUrl: r.platformUrl, attempts: Number(r.attempts || 0), lastError: r.lastError
  };
}

/** Create or update a post and its per-platform versions. */
function savePost(input) {
  Db.ensure();
  if (!input) throw new Error('Nothing to save');
  var status = POST_STATUSES.indexOf(input.status) !== -1 ? input.status : 'draft';
  var platforms = (input.platforms || []).filter(function (p) { return PLATFORM_IDS.indexOf(p) !== -1; });
  if (status === 'scheduled') {
    if (!platforms.length) throw new Error('Choose at least one platform before scheduling.');
    var when = new Date(input.scheduledAt);
    if (isNaN(when.getTime())) throw new Error('Choose a date and time to schedule this post.');
    if (when.getTime() < Date.now() + 5 * 60000) throw new Error('Pick a time at least 5 minutes from now.');
  }

  var postRow = {
    title: String(input.title || '').slice(0, 200) || 'Untitled post',
    postType: input.postType || 'photo',
    status: status,
    baseCaption: String(input.baseCaption || '').slice(0, 70000),
    baseHashtags: String(input.baseHashtags || '').slice(0, 5000),
    link: String(input.link || '').slice(0, 2048),
    mediaIds: input.mediaIds || [],
    platforms: platforms,
    scheduledAt: input.scheduledAt || '',
    timeZone: APP.timeZone,
    inQueue: !!input.inQueue,
    notes: String(input.notes || '').slice(0, 5000)
  };

  return Db.withLock(function () {
    var saved;
    if (input.id && Db.get('Posts', input.id)) {
      saved = Db.update('Posts', input.id, postRow);
      Db.removeWhere('PostTargets', 'postId', input.id);
    } else {
      saved = Db.insert('Posts', postRow);
    }
    var targets = input.targets || {};
    platforms.forEach(function (p) {
      var t = targets[p] || {};
      var options = t.options || {};
      options.customize = !!t.customize;
      Db.insert('PostTargets', {
        postId: saved.id, platform: p, format: t.format || '',
        caption: t.customize ? String(t.caption || '') : '',
        hashtags: t.customize ? String(t.hashtags || '') : '',
        title: String(t.title || '').slice(0, 200),
        description: String(t.description || '').slice(0, 6000),
        destinationUrl: String(t.destinationUrl || '').slice(0, 2048),
        coverMediaId: t.coverMediaId || '',
        mediaIds: t.mediaIds || [],
        options: options,
        status: status === 'scheduled' ? 'scheduled' : 'draft',
        scheduledAt: postRow.scheduledAt, attempts: 0
      });
    });
    Db.log(status === 'scheduled' ? 'info' : 'info', 'post',
      (status === 'scheduled' ? 'Scheduled “' : 'Saved draft “') + postRow.title + '”', { postId: saved.id });
    return getPost(saved.id);
  });
}

/** One post with its platform versions. */
function getPost(id) {
  var row = Db.get('Posts', id);
  if (!row) throw new Error('Post not found');
  var post = parsePost_(row);
  var targets = {};
  Db.all('PostTargets').filter(function (t) { return t.postId === id; }).forEach(function (t) {
    var pt = parseTarget_(t);
    targets[pt.platform] = pt;
  });
  post.targets = targets;
  return post;
}

/** Posts for the lists (Drafts, Scheduled, dashboard), with a cover thumbnail. */
function listPosts(filter) {
  filter = filter || {};
  var media = {};
  Db.all('Media').forEach(function (m) { media[m.id] = { thumbData: m.thumbData, kind: m.kind, durationSec: m.durationSec }; });
  var targets = {};
  Db.all('PostTargets').forEach(function (t) {
    (targets[t.postId] = targets[t.postId] || []).push({ platform: t.platform, status: t.status, format: t.format, lastError: t.lastError });
  });
  return Db.all('Posts').map(parsePost_).filter(function (p) {
    return !filter.status || filter.status.indexOf(p.status) !== -1;
  }).map(function (p) {
    var first = media[p.mediaIds[0]] || null;
    p.cover = first ? { thumbData: first.thumbData, kind: first.kind, durationSec: Number(first.durationSec) || null } : null;
    p.mediaCount = p.mediaIds.length;
    p.targets = targets[p.id] || [];
    return p;
  }).sort(function (a, b) {
    var ka = a.status === 'draft' ? a.updatedAt : a.scheduledAt;
    var kb = b.status === 'draft' ? b.updatedAt : b.scheduledAt;
    return a.status === 'draft' ? (ka < kb ? 1 : -1) : (ka > kb ? 1 : -1);
  });
}

function deletePost(id) {
  Db.ensure();
  var row = Db.get('Posts', id);
  Db.withLock(function () {
    Db.removeWhere('PostTargets', 'postId', id);
    Db.removeWhere('Posts', 'id', id);
  });
  if (row) Db.log('info', 'post', 'Deleted “' + row.title + '”');
  return { ok: true };
}

function duplicatePost(id) {
  var p = getPost(id);
  var copy = {
    title: p.title + ' (copy)', postType: p.postType, status: 'draft',
    baseCaption: p.baseCaption, baseHashtags: p.baseHashtags, link: p.link,
    mediaIds: p.mediaIds, platforms: p.platforms, scheduledAt: '', notes: p.notes, targets: {}
  };
  Object.keys(p.targets).forEach(function (k) {
    var t = p.targets[k];
    copy.targets[k] = { customize: t.customize, caption: t.caption, hashtags: t.hashtags, title: t.title,
      description: t.description, destinationUrl: t.destinationUrl, format: t.format,
      coverMediaId: t.coverMediaId, mediaIds: t.mediaIds, options: t.options };
  });
  return savePost(copy);
}

function moveToDrafts(id) {
  Db.ensure();
  Db.withLock(function () {
    Db.update('Posts', id, { status: 'draft', inQueue: false });
    Db.all('PostTargets').filter(function (t) { return t.postId === id; }).forEach(function (t) {
      Db.update('PostTargets', t.id, { status: 'draft' });
    });
  });
  return getPost(id);
}

/** Read a value from the Settings tab. */
function getSetting_(key, fallback) {
  var rows = Db.all('Settings').filter(function (r) { return r.key === key; });
  return rows.length ? rows[0].value : fallback;
}

/**
 * Next free publishing-queue slot (Atlantic Time). Slots come from Settings › queueSlots,
 * e.g. Tue 10:00, Thu 18:30, Sat 10:00. A slot is "taken" if a scheduled post is within an hour of it.
 */
function nextQueueSlot() {
  Db.ensure();
  var slots = json_(getSetting_('queueSlots', DEFAULT_SETTINGS.queueSlots), []);
  if (!slots.length) return null;
  var taken = Db.all('Posts').filter(function (p) { return p.status === 'scheduled'; })
    .map(function (p) { return new Date(p.scheduledAt).getTime(); });
  var tz = APP.timeZone;
  var now = Date.now() + 30 * 60000;
  for (var d = 0; d < 60; d++) {
    var day = new Date(Date.now() + d * 86400000);
    var ymd = Utilities.formatDate(day, tz, 'yyyy-MM-dd');
    var dow = Number(Utilities.formatDate(day, tz, 'u')) % 7; // 0 = Sunday
    for (var i = 0; i < slots.length; i++) {
      if (Number(slots[i].day) !== dow) continue;
      var at = Utilities.parseDate(ymd + ' ' + slots[i].time, tz, 'yyyy-MM-dd HH:mm').getTime();
      if (at < now) continue;
      var clash = taken.some(function (t) { return Math.abs(t - at) < 3600000; });
      if (!clash) return { iso: new Date(at).toISOString() };
    }
  }
  return null;
}
